'use client';

// Wraps Editor.Field parts. Does not wrap Root. Cms controls need
// CmsSourcesProvider from editor-form-cms.

import {
  Editor,
  useAnyBlock,
  useEditor,
  usePalette,
  useSelection,
} from '@createcms/react/editor';
import * as React from 'react';

import { cn } from '@/lib/utils';

function Field({
  className,
  ...props
}: React.ComponentProps<typeof Editor.Field>) {
  return (
    <Editor.Field
      data-slot="editor-field"
      className={cn(
        'flex flex-col gap-1.5',
        'data-[kind=boolean]:grid data-[kind=boolean]:grid-cols-[auto_1fr] data-[kind=boolean]:items-center data-[kind=boolean]:gap-x-2 data-[kind=boolean]:gap-y-1',
        'data-[kind=boolean]:[&>[data-slot=editor-field-control]]:col-start-1 data-[kind=boolean]:[&>[data-slot=editor-field-control]]:row-start-1 data-[kind=boolean]:[&>[data-slot=editor-field-control]]:w-fit',
        'data-[kind=boolean]:[&>[data-slot=editor-field-label]]:col-start-2 data-[kind=boolean]:[&>[data-slot=editor-field-label]]:row-start-1',
        'data-[kind=boolean]:[&>[data-slot=editor-field-description]]:col-start-2',
        'data-[kind=boolean]:[&>[data-slot=editor-field-error]]:col-start-2',
        className,
      )}
      {...props}
    />
  );
}

function FieldLabel({
  className,
  ...props
}: React.ComponentProps<typeof Editor.FieldLabel>) {
  return (
    <Editor.FieldLabel
      data-slot="editor-field-label"
      className={cn(
        'text-sm leading-none font-medium data-required:after:ml-0.5 data-required:after:content-["*"]',
        className,
      )}
      {...props}
    />
  );
}

function FieldControl(props: React.ComponentProps<typeof Editor.FieldControl>) {
  return (
    <div data-slot="editor-field-control" className="w-full">
      <Editor.FieldControl {...props} />
    </div>
  );
}

function FieldDescription({
  className,
  ...props
}: React.ComponentProps<typeof Editor.FieldDescription>) {
  return (
    <Editor.FieldDescription
      data-slot="editor-field-description"
      className={cn('text-sm text-editor-muted', className)}
      {...props}
    />
  );
}

function FieldError({
  className,
  ...props
}: React.ComponentProps<typeof Editor.FieldError>) {
  return (
    <Editor.FieldError
      data-slot="editor-field-error"
      className={cn('text-sm text-editor-invalid', className)}
      {...props}
    />
  );
}

function Form({
  className,
  ...props
}: React.ComponentProps<typeof Editor.Form>) {
  return (
    <Editor.Form
      data-slot="editor-form"
      className={cn(
        'flex flex-col gap-4',
        '[&>div]:flex [&>div]:flex-col [&>div]:gap-1.5',
        '[&>div[data-kind=boolean]]:grid [&>div[data-kind=boolean]]:grid-cols-[auto_1fr] [&>div[data-kind=boolean]]:items-center [&>div[data-kind=boolean]]:gap-x-2 [&>div[data-kind=boolean]]:gap-y-1',
        '[&>div[data-kind=boolean]>label]:col-start-2 [&>div[data-kind=boolean]>label]:row-start-1',
        '[&>div[data-kind=boolean]>[data-slot=checkbox]]:col-start-1 [&>div[data-kind=boolean]>[data-slot=checkbox]]:row-start-1',
        '[&>div[data-kind=boolean]>:not(label):not([data-slot=checkbox])]:col-start-2',
        '[&_fieldset]:flex [&_fieldset]:flex-col [&_fieldset]:gap-4',
        '[&_fieldset>div]:flex [&_fieldset>div]:flex-col [&_fieldset>div]:gap-1.5',
        '[&_legend]:text-sm [&_legend]:font-medium',
        className,
      )}
      {...props}
    />
  );
}

function FormSurface({ className, ...props }: React.ComponentProps<'div'>) {
  const rootId = useEditor((state) => state.rootId);
  const selected = useSelection().selected;
  const blockId = selected ?? rootId;
  const block = useAnyBlock(blockId);
  const palette = usePalette();
  const label =
    blockId === rootId
      ? 'Page'
      : (palette.find((item) => item.type === block?.type)?.label ??
        block?.type ??
        'Block');

  return (
    <div
      data-slot="editor-form-surface"
      className={cn(
        'mx-auto min-h-0 w-full max-w-xl flex-1 overflow-y-auto px-6 py-8',
        className,
      )}
      {...props}
    >
      <h1 className="mb-6 text-lg font-semibold tracking-tight">{label}</h1>
      <Form blockId={blockId} />
    </div>
  );
}

export {
  Field,
  FieldControl,
  FieldDescription,
  FieldError,
  FieldLabel,
  Form,
  FormSurface,
};
export { CmsSourcesProvider, cmsFields } from './editor-form-cms';

'use client';

import type { FieldControlProps, FieldControls } from '@createcms/react/editor';
import type {
  CmsAssetListItem,
  CmsFieldSources,
  CmsRootListItem,
} from '@createcms/react/editor/cms';

import {
  emptyListElement,
  fromDatetimeLocal,
  toDatetimeLocal,
} from '@createcms/react/editor';
import {
  assetUrl,
  referenceLabel,
  useVariableSuggest,
} from '@createcms/react/editor/cms';
import * as React from 'react';
import { createPortal } from 'react-dom';

import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';

const CmsSourcesContext = React.createContext<CmsFieldSources | null>(null);

export function CmsSourcesProvider({
  sources,
  children,
}: {
  sources: CmsFieldSources;
  children: React.ReactNode;
}) {
  return (
    <CmsSourcesContext.Provider value={sources}>
      {children}
    </CmsSourcesContext.Provider>
  );
}

function useCmsSources(): CmsFieldSources {
  const value = React.useContext(CmsSourcesContext);
  if (!value) {
    throw new Error('CmsSourcesProvider is required for cms field controls');
  }
  return value;
}

function fieldAria(props: {
  describedBy: string | undefined;
  invalid: boolean;
  required: boolean;
}) {
  return {
    'aria-describedby': props.describedBy,
    'aria-invalid': props.invalid || undefined,
    'aria-required': props.required || undefined,
  } as const;
}

function StringField(props: FieldControlProps<'string'>) {
  return (
    <Input
      type="text"
      id={props.id}
      name={props.name}
      value={props.value ?? ''}
      placeholder={props.spec.placeholder}
      required={props.required}
      disabled={props.disabled}
      minLength={props.spec.minLength}
      maxLength={props.spec.maxLength}
      {...fieldAria(props)}
      onChange={(event) => props.onChange(event.currentTarget.value)}
    />
  );
}

function NumberField(props: FieldControlProps<'number'>) {
  return (
    <Input
      type="number"
      id={props.id}
      name={props.name}
      value={props.value ?? ''}
      placeholder={props.spec.placeholder}
      required={props.required}
      disabled={props.disabled}
      min={props.spec.min}
      max={props.spec.max}
      {...fieldAria(props)}
      onChange={(event) => {
        const raw = event.currentTarget.value;
        props.onChange(raw === '' ? undefined : Number(raw));
      }}
    />
  );
}

function BooleanField(props: FieldControlProps<'boolean'>) {
  return (
    <Checkbox
      id={props.id}
      name={props.name}
      checked={props.value ?? false}
      required={props.required}
      disabled={props.disabled}
      {...fieldAria(props)}
      onCheckedChange={(checked) => props.onChange(checked === true)}
    />
  );
}

function DateField(props: FieldControlProps<'date'>) {
  return (
    <Input
      type="datetime-local"
      id={props.id}
      name={props.name}
      value={toDatetimeLocal(props.value)}
      required={props.required}
      disabled={props.disabled}
      {...fieldAria(props)}
      onChange={(event) =>
        props.onChange(fromDatetimeLocal(event.currentTarget.value))
      }
    />
  );
}

function SelectField(props: FieldControlProps<'select'>) {
  return (
    <Select
      id={props.id}
      name={props.name}
      value={props.value ?? null}
      required={props.required}
      disabled={props.disabled}
      items={props.spec.options.map((option) => ({
        value: option.value,
        label: option.label,
      }))}
      onValueChange={(value) =>
        props.onChange(value === null || value === '' ? undefined : value)
      }
    >
      <SelectTrigger className="w-full" {...fieldAria(props)}>
        <SelectValue placeholder={props.spec.placeholder ?? ''} />
      </SelectTrigger>
      <SelectContent>
        {props.spec.options.map((option) => (
          <SelectItem key={option.value} value={option.value}>
            {option.label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

const PAGE_SIZE = 20;

function labelFromRoot(root: CmsRootListItem): string {
  const props = root.properties ?? {};
  for (const key of ['title', 'label', 'name'] as const) {
    const value = props[key];
    if (typeof value === 'string' && value.length > 0) return value;
  }
  if (root.slug) return root.slug;
  if (root.path) return root.path;
  return root.id;
}

function RootPickerDialog({
  collection,
  value,
  onSelect,
  disabled,
  triggerLabel,
}: {
  collection: string;
  value: string | undefined;
  onSelect: (rootId: string) => void;
  disabled: boolean;
  triggerLabel: string;
}) {
  const sources = useCmsSources();
  const [open, setOpen] = React.useState(false);
  const [search, setSearch] = React.useState('');
  const [offset, setOffset] = React.useState(0);
  const [roots, setRoots] = React.useState<CmsRootListItem[]>([]);
  const [hasMore, setHasMore] = React.useState(false);
  const [label, setLabel] = React.useState<string | null>(null);

  React.useEffect(() => {
    if (!value) {
      setLabel(null);
      return;
    }
    let cancelled = false;
    void referenceLabel(collection, value, sources).then((text) => {
      if (!cancelled) setLabel(text);
    });
    return () => {
      cancelled = true;
    };
  }, [collection, sources, value]);

  const load = React.useCallback(async () => {
    const page = await sources.roots.list(collection, {
      search: search || undefined,
      limit: PAGE_SIZE,
      offset,
    });
    setRoots(page.roots);
    setHasMore(page.hasMore);
  }, [collection, offset, search, sources.roots]);

  React.useEffect(() => {
    if (!open) return;
    void load();
  }, [load, open]);

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger
        render={
          <Button
            type="button"
            variant="outline"
            disabled={disabled}
            className="w-full justify-start font-normal"
          >
            {value ? (label ?? value) : triggerLabel}
          </Button>
        }
      />
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>{triggerLabel}</DialogTitle>
        </DialogHeader>
        <Input
          placeholder="Search"
          value={search}
          onChange={(event) => {
            setSearch(event.target.value);
            setOffset(0);
          }}
        />
        <ul className="flex max-h-64 flex-col gap-1 overflow-y-auto">
          {roots.map((root) => (
            <li key={root.id}>
              <Button
                type="button"
                variant="ghost"
                className="w-full justify-start"
                onClick={() => {
                  onSelect(root.id);
                  setOpen(false);
                }}
              >
                {labelFromRoot(root)}
              </Button>
            </li>
          ))}
        </ul>
        <DialogFooter>
          <Button
            type="button"
            variant="outline"
            size="sm"
            disabled={offset === 0}
            onClick={() => setOffset((prev) => Math.max(0, prev - PAGE_SIZE))}
          >
            Previous
          </Button>
          <Button
            type="button"
            variant="outline"
            size="sm"
            disabled={!hasMore}
            onClick={() => setOffset((prev) => prev + PAGE_SIZE)}
          >
            Next
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

function MediaField(props: FieldControlProps<'image'>) {
  const sources = useCmsSources();
  const upload = sources.assets.useUpload();
  const fileInputRef = React.useRef<HTMLInputElement>(null);
  const expectingUploadRef = React.useRef(false);
  const [open, setOpen] = React.useState(false);
  const [search, setSearch] = React.useState('');
  const [offset, setOffset] = React.useState(0);
  const [assets, setAssets] = React.useState<CmsAssetListItem[]>([]);
  const [hasMore, setHasMore] = React.useState(false);

  const loadAssets = React.useCallback(async () => {
    const page = await sources.assets.list({
      search: search || undefined,
      limit: PAGE_SIZE,
      offset,
    });
    setAssets(page.assets);
    setHasMore(page.hasMore);
  }, [offset, search, sources.assets]);

  React.useEffect(() => {
    if (!open) return;
    void loadAssets();
  }, [loadAssets, open]);

  React.useEffect(() => {
    if (!expectingUploadRef.current || upload.isUploading) return;

    expectingUploadRef.current = false;
    if (upload.error) return;

    const uploaded = upload.files.find((file) => file.result?.id);
    if (uploaded?.result?.id) {
      props.onChange(uploaded.result.id);
      void loadAssets();
    }
  }, [
    loadAssets,
    props.onChange,
    upload.error,
    upload.files,
    upload.isUploading,
  ]);

  const previewUrl = props.value ? assetUrl(props.value) : null;

  return (
    <div id={props.id} className="flex flex-col gap-2" {...fieldAria(props)}>
      {previewUrl ? (
        <img
          src={previewUrl}
          alt=""
          className="max-h-32 w-auto rounded-md border object-contain"
        />
      ) : null}
      <div className="flex flex-wrap gap-2">
        <Dialog open={open} onOpenChange={setOpen}>
          <DialogTrigger
            render={
              <Button
                type="button"
                variant="outline"
                disabled={props.disabled}
                aria-describedby={props.describedBy}
                aria-invalid={props.invalid || undefined}
                aria-required={props.required || undefined}
              >
                {props.value ? 'Change image' : 'Select image'}
              </Button>
            }
          />
          <DialogContent className="max-w-md">
            <DialogHeader>
              <DialogTitle>Select image</DialogTitle>
            </DialogHeader>
            <Input
              placeholder="Search assets"
              value={search}
              onChange={(event) => {
                setSearch(event.target.value);
                setOffset(0);
              }}
            />
            <ul className="flex max-h-64 flex-col gap-1 overflow-y-auto">
              {assets.map((asset) => (
                <li key={asset.id}>
                  <Button
                    type="button"
                    variant="ghost"
                    className="w-full justify-start"
                    onClick={() => {
                      props.onChange(asset.id);
                      setOpen(false);
                    }}
                  >
                    {asset.slug || asset.id}
                  </Button>
                </li>
              ))}
            </ul>
            <DialogFooter>
              <Button
                type="button"
                variant="outline"
                size="sm"
                disabled={offset === 0}
                onClick={() =>
                  setOffset((prev) => Math.max(0, prev - PAGE_SIZE))
                }
              >
                Previous
              </Button>
              <Button
                type="button"
                variant="outline"
                size="sm"
                disabled={!hasMore}
                onClick={() => setOffset((prev) => prev + PAGE_SIZE)}
              >
                Next
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
        <Button
          type="button"
          variant="outline"
          disabled={props.disabled || upload.isUploading}
          onClick={() => fileInputRef.current?.click()}
        >
          {upload.isUploading ? 'Uploading…' : 'Upload'}
        </Button>
        <input
          ref={fileInputRef}
          type="file"
          accept="image/*"
          className="sr-only"
          disabled={props.disabled || upload.isUploading}
          onChange={(event) => {
            const files = event.target.files;
            if (!files?.length) return;
            expectingUploadRef.current = true;
            void upload.upload(Array.from(files));
            event.target.value = '';
          }}
        />
        {props.value ? (
          <Button
            type="button"
            variant="ghost"
            disabled={props.disabled}
            onClick={() => props.onChange(undefined)}
          >
            Clear
          </Button>
        ) : null}
      </div>
    </div>
  );
}

function ReferencePicker(props: FieldControlProps<'reference'>) {
  return (
    <div id={props.id} className="flex flex-col gap-2" {...fieldAria(props)}>
      <RootPickerDialog
        collection={props.spec.collection}
        value={props.value}
        disabled={props.disabled}
        triggerLabel="Select reference"
        onSelect={(rootId) => props.onChange(rootId)}
      />
    </div>
  );
}

const LINK_KINDS = ['internal', 'external', 'email', 'phone'] as const;

function LinkField(props: FieldControlProps<'link'>) {
  const allowed = props.spec.allowedKinds ?? [...LINK_KINDS];
  const kind = props.value?.kind ?? allowed[0] ?? 'external';
  const collections = props.spec.allowedCollections ?? [];

  const setKind = (next: (typeof LINK_KINDS)[number]) => {
    switch (next) {
      case 'internal':
        props.onChange({
          kind: 'internal',
          rootId: '',
          collection: collections[0] ?? '',
        });
        break;
      case 'external':
        props.onChange({ kind: 'external', url: '' });
        break;
      case 'email':
        props.onChange({ kind: 'email', email: '' });
        break;
      case 'phone':
        props.onChange({ kind: 'phone', phone: '' });
        break;
    }
  };

  return (
    <div id={props.id} className="flex flex-col gap-2" {...fieldAria(props)}>
      <Select
        value={kind}
        disabled={props.disabled}
        onValueChange={(value) => {
          if (value === null) return;
          setKind(value as (typeof LINK_KINDS)[number]);
        }}
      >
        <SelectTrigger className="w-full">
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {allowed.map((item) => (
            <SelectItem key={item} value={item}>
              {item}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      {kind === 'internal' ? (
        <div className="flex flex-col gap-2">
          {collections.length > 1 ? (
            <Select
              value={
                props.value?.kind === 'internal'
                  ? props.value.collection
                  : (collections[0] ?? null)
              }
              disabled={props.disabled}
              onValueChange={(value) => {
                if (value === null) return;
                const rootId =
                  props.value?.kind === 'internal' ? props.value.rootId : '';
                props.onChange({
                  kind: 'internal',
                  rootId,
                  collection: value,
                });
              }}
            >
              <SelectTrigger className="w-full">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {collections.map((name) => (
                  <SelectItem key={name} value={name}>
                    {name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          ) : collections.length === 0 ? (
            <Input
              placeholder="Collection"
              disabled={props.disabled}
              value={
                props.value?.kind === 'internal' ? props.value.collection : ''
              }
              onChange={(event) => {
                const rootId =
                  props.value?.kind === 'internal' ? props.value.rootId : '';
                props.onChange({
                  kind: 'internal',
                  rootId,
                  collection: event.target.value,
                });
              }}
            />
          ) : null}
          <RootPickerDialog
            collection={
              props.value?.kind === 'internal'
                ? props.value.collection
                : (collections[0] ?? '')
            }
            value={
              props.value?.kind === 'internal' ? props.value.rootId : undefined
            }
            disabled={props.disabled}
            triggerLabel="Select page"
            onSelect={(rootId) => {
              const col =
                props.value?.kind === 'internal'
                  ? props.value.collection
                  : (collections[0] ?? '');
              props.onChange({ kind: 'internal', rootId, collection: col });
            }}
          />
        </div>
      ) : null}
      {kind === 'external' ? (
        <Input
          placeholder="https://"
          disabled={props.disabled}
          value={props.value?.kind === 'external' ? props.value.url : ''}
          onChange={(event) =>
            props.onChange({ kind: 'external', url: event.target.value })
          }
        />
      ) : null}
      {kind === 'email' ? (
        <Input
          type="email"
          placeholder="name@example.com"
          disabled={props.disabled}
          value={props.value?.kind === 'email' ? props.value.email : ''}
          onChange={(event) =>
            props.onChange({ kind: 'email', email: event.target.value })
          }
        />
      ) : null}
      {kind === 'phone' ? (
        <Input
          type="tel"
          placeholder="+1 555 0100"
          disabled={props.disabled}
          value={props.value?.kind === 'phone' ? props.value.phone : ''}
          onChange={(event) =>
            props.onChange({ kind: 'phone', phone: event.target.value })
          }
        />
      ) : null}
    </div>
  );
}

function RichTextField(props: FieldControlProps<'richText'>) {
  const sources = useCmsSources();
  const suggest = useVariableSuggest(sources);
  const textareaRef = React.useRef<HTMLTextAreaElement>(null);
  const [highlighted, setHighlighted] = React.useState(0);
  const [suggestOpen, setSuggestOpen] = React.useState(false);
  const [suggestQuery, setSuggestQuery] = React.useState('');
  const [suggestRect, setSuggestRect] = React.useState<DOMRect | null>(null);

  const items = suggestOpen ? suggest.getItems(suggestQuery) : [];

  const updateSuggest = (text: string, caret: number) => {
    const prefix = text.slice(0, caret);
    const match = prefix.match(suggest.pattern);
    if (!match) {
      setSuggestOpen(false);
      return;
    }
    setSuggestQuery(match[1] ?? '');
    setSuggestOpen(true);
    setHighlighted(0);
    const textarea = textareaRef.current;
    if (textarea) {
      setSuggestRect(textarea.getBoundingClientRect());
    }
  };

  const accept = (index: number) => {
    const item = items[index];
    const textarea = textareaRef.current;
    if (!item || !textarea) return;
    const caret = textarea.selectionStart;
    const text = props.value ?? '';
    const prefix = text.slice(0, caret);
    const match = prefix.match(suggest.pattern);
    if (!match) return;
    const start = caret - match[0].length;
    const next = text.slice(0, start) + item.insertText + text.slice(caret);
    props.onChange(next);
    setSuggestOpen(false);
    requestAnimationFrame(() => {
      const pos = start + item.insertText.length;
      textarea.setSelectionRange(pos, pos);
      textarea.focus();
    });
  };

  return (
    <div className="relative">
      <Textarea
        ref={textareaRef}
        id={props.id}
        name={props.name}
        disabled={props.disabled}
        value={props.value ?? ''}
        rows={4}
        {...fieldAria(props)}
        onChange={(event) => {
          props.onChange(event.target.value);
          updateSuggest(event.target.value, event.target.selectionStart);
        }}
        onKeyDown={(event) => {
          if (!suggestOpen || items.length === 0) return;
          if (event.key === 'ArrowDown') {
            event.preventDefault();
            setHighlighted((prev) => (prev + 1) % items.length);
          } else if (event.key === 'ArrowUp') {
            event.preventDefault();
            setHighlighted((prev) => (prev - 1 + items.length) % items.length);
          } else if (event.key === 'Enter') {
            event.preventDefault();
            accept(highlighted);
          } else if (event.key === 'Escape') {
            event.preventDefault();
            setSuggestOpen(false);
          }
        }}
        onBlur={() => {
          window.setTimeout(() => setSuggestOpen(false), 150);
        }}
      />
      {suggestOpen && items.length > 0 && suggestRect
        ? createPortal(
            <div
              className="bg-popover border-border z-50 rounded-md border shadow-md"
              style={{
                position: 'fixed',
                top: suggestRect.bottom + 4,
                left: suggestRect.left,
                minWidth: suggestRect.width,
              }}
            >
              {suggest.render({
                items,
                highlighted,
                query: suggestQuery,
                rect: suggestRect,
                accept,
              })}
            </div>,
            document.body,
          )
        : null}
    </div>
  );
}

function ListField(props: FieldControlProps<'list'>) {
  const items = props.value ?? [];
  const { min = 0, max = Number.POSITIVE_INFINITY } = props.spec;
  const update = (next: Array<string | number | boolean>) =>
    props.onChange(next);
  const swap = (from: number, to: number) => {
    const next = [...items];
    const [moved] = next.splice(from, 1);
    if (moved !== undefined) next.splice(to, 0, moved);
    update(next);
  };

  return (
    <div
      id={props.id}
      role="group"
      data-slot="editor-list"
      className="flex flex-col gap-2"
      {...fieldAria(props)}
    >
      <ol className="flex flex-col gap-2">
        {items.map((item, index) => (
          <li
            key={index}
            className="border-border flex flex-col gap-2 rounded-md border p-2"
          >
            {props.renderElement?.({
              spec: {
                ...props.spec.of,
                label: `${props.spec.label} ${index + 1}`,
              },
              value: item,
              onChange: (next) => {
                const copy = [...items];
                copy[index] = next as string | number | boolean;
                update(copy);
              },
              id: `${props.id}-${index}`,
              name: `${props.name}[${index}]`,
              index,
              disabled: props.disabled,
              invalid: false,
              describedBy: undefined,
            })}
            <div className="flex flex-wrap gap-1">
              <Button
                type="button"
                variant="outline"
                size="xs"
                aria-label={`Move ${props.spec.label} ${index + 1} up`}
                disabled={props.disabled || index === 0}
                onClick={() => swap(index, index - 1)}
              >
                Up
              </Button>
              <Button
                type="button"
                variant="outline"
                size="xs"
                aria-label={`Move ${props.spec.label} ${index + 1} down`}
                disabled={props.disabled || index === items.length - 1}
                onClick={() => swap(index, index + 1)}
              >
                Down
              </Button>
              <Button
                type="button"
                variant="outline"
                size="xs"
                aria-label={`Remove ${props.spec.label} ${index + 1}`}
                disabled={props.disabled || items.length <= min}
                onClick={() => update(items.filter((_, i) => i !== index))}
              >
                Remove
              </Button>
            </div>
          </li>
        ))}
      </ol>
      <Button
        type="button"
        variant="outline"
        size="sm"
        aria-label={`Add ${props.spec.label}`}
        disabled={props.disabled || items.length >= max}
        onClick={() => update([...items, emptyListElement(props.spec.of)])}
      >
        Add
      </Button>
    </div>
  );
}

